/**
 * @event
 * @name scwin.grd_qnaList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_qnaList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_qnaList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_qnaList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.searchQnaView === 'function') { await scwin.searchQnaView(r["quesReadYn"], r["contnId"], r["contnGrpId"], r["ansObjContnId"], r["notiObjSysTpCd"], r["contnAttachSeq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.searchQnaView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.searchQnaView'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_qnaList.oncellclick' });
    }
};

