    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_qnaList_fmt_column2
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_qnaList_fmt_column2 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_qnaList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "quesBzTpCd") ?? '') : '');
        if (v === '1') { return "상장"; }
        if (v === '2') { return "공시"; }
        if (v === '3') { return "지분"; }
        if (v === '9') { return "기타"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_qnaList.column2" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.grd_qnaList_fmt_quesTitle
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_qnaList_fmt_quesTitle = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_qnaList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "contnDepth") ?? '') : '');
        if (v !== '1') { return (console.error('[sdd] 미실현 라벨 갈래: quesTitle (image)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_qnaList.quesTitle" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.goWriteQna
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goWriteQna = async function () {
    /* sdd-asis-lifecycle:begin fn_goWriteQna — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.QnaInfoForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goWriteQnaReq').set('method', 'writeQna');
    { const nr = await scwin.tx_fn_goWriteQna(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil17301/jldfil17301.xml", { "method": 'writeQna' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.QnaListForm || { elements: [] });
    frm.action = 'qna.do';
    $c.util.getComponent('dma_goWriteQnaReq').set('method', 'searchQnaList');
    await scwin.tx_fn_search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchQnaView
 * @author Inswave
 * @date 2026. 09. 29
 * @param quesReadYn contnId contnGrpId ansObjContnId notiObjSysTpCd contnAttachSeq
 * @returns
 * @hidden N
*/
scwin.searchQnaView = async function (quesReadYn, contnId, contnGrpId, ansObjContnId, notiObjSysTpCd, contnAttachSeq) {
    /* sdd-asis-lifecycle:begin fn_SearchQnaView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (quesReadYn === 'Y') {
        const frm = (document.QnaListForm || { elements: [] });
        frm.action = 'qna.do';
        $c.util.getComponent('dma_goWriteQnaReq').set('method', 'searchQnaView');
        $c.util.getComponent('dma_goWriteQnaReq').set('contnId', contnId);
        $c.util.getComponent('dma_goWriteQnaReq').set('contnGrpId', contnGrpId);
        $c.util.getComponent('dma_goWriteQnaReq').set('ansObjContnId', ansObjContnId);
        $c.util.getComponent('dma_goWriteQnaReq').set('notiObjSysTpCd', notiObjSysTpCd);
        $c.util.getComponent('dma_goWriteQnaReq').set('contnAttachSeq', contnAttachSeq);
        { const nr = await scwin.tx_fn_SearchQnaView(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil17302/jldfil17302.xml", { "method": 'searchQnaView', "contnId": contnId, "contnGrpId": contnGrpId, "ansObjContnId": ansObjContnId, "notiObjSysTpCd": notiObjSysTpCd, "contnAttachSeq": contnAttachSeq }); } };
    } else {
        await $c.win.alert('비공개로 작성된 글은 작성자만 볼 수 있습니다.');
        return;
    }
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_142_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_142_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_142.page' }); } scwin.tx_fn_search(); };
